'use strict';
// Optional provider integration: Clerk JS quickstart and session reference, checked 2026-09-09.
// https://clerk.com/docs/js-frontend/getting-started/quickstart
// https://clerk.com/docs/js-frontend/reference/objects/session
const state={user:null,csrf:'',view:'discover',properties:[],room:null,authConfig:{mode:'unknown'},clerk:null,identityError:null};
function clearPrivateState(){state.identityRevision=(state.identityRevision||0)+1;state.user=null;state.csrf='';state.operatorKey='';state.room=null;inspectRecords.clear()}
function clerkOrigin(config){if(!/^pk_(test|live)_[A-Za-z0-9_-]+$/.test(config.publishable_key||''))throw Error('Clerk publishable key is missing or invalid.');const issuer=new URL(config.issuer);if(issuer.protocol!=='https:'||issuer.username||issuer.password||issuer.search||issuer.hash||!['','/'].includes(issuer.pathname)||issuer.port)throw Error('Clerk issuer must be a configured HTTPS origin.');const encoded=config.publishable_key.split('_').slice(2).join('_').replaceAll('-','+').replaceAll('_','/');let decoded;try{decoded=atob(encoded+'='.repeat((4-encoded.length%4)%4))}catch{throw Error('Clerk publishable key cannot be decoded.')}if(!decoded.endsWith('$')||decoded.slice(0,-1)!==issuer.hostname)throw Error('Clerk publishable key and issuer do not match.');if(!Array.isArray(config.authorized_parties)||!config.authorized_parties.includes(location.origin))throw Error('This application origin is not authorized for the configured identity provider.');return issuer.origin}
function loadIdentityScript(src,publishableKey){return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.async=true;script.crossOrigin='anonymous';if(publishableKey)script.dataset.clerkPublishableKey=publishableKey;const timer=setTimeout(()=>{script.remove();reject(Error('Identity provider did not load. Check the configured issuer and content-security policy.'))},20000);script.onload=()=>{clearTimeout(timer);resolve()};script.onerror=()=>{clearTimeout(timer);reject(Error('Identity provider script was blocked or unavailable. Local password sign-in is disabled in Clerk mode.'))};document.head.appendChild(script)})}
async function initializeIdentity(){const response=await fetch('/api/auth/config',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error('Identity configuration could not be loaded.');const config=await response.json();if(!['demo','clerk'].includes(config.mode))throw Error('Unsupported identity mode.');state.authConfig=config;if(config.mode==='demo')return;const origin=clerkOrigin(config);await loadIdentityScript(`${origin}/npm/@clerk/ui@1/dist/ui.browser.js`);await loadIdentityScript(`${origin}/npm/@clerk/clerk-js@6/dist/clerk.browser.js`,config.publishable_key);if(!window.Clerk?.load)throw Error('Clerk SDK did not initialize.');await window.Clerk.load({ui:{ClerkUI:window.__internal_ClerkUICtor}});state.clerk=window.Clerk;state.lastClerkSession=state.clerk.session?.id||null;state.clerk.addListener(({session})=>{const id=session?.id||null;if(id===state.lastClerkSession)return;state.lastClerkSession=id;clearPrivateState();state.identityError=null;unmountIdentityWidget();if(!id){route();return}refreshIdentitySession().then(()=>route()).catch(e=>{state.identityError=e.message;route()})},{skipInitialEmit:true})}
async function identityHeaders(path){if(!path.startsWith('/api/')||path.startsWith('/api/auth/config')||state.authConfig.mode!=='clerk'||!state.clerk?.session)return {};const token=await state.clerk.session.getToken();return token?{Authorization:`Bearer ${token}`}:{}}
async function refreshIdentitySession(){try{const d=await api('/api/session');state.user=d.user;state.csrf=d.csrf||'';state.identityError=null}catch(e){if(e.stale)throw e;clearPrivateState();state.identityError=e.message;if(state.authConfig.mode==='clerk'&&e.status===403){state.identityError='Your Clerk identity is signed in but has not been provisioned for this workspace. An administrator must explicitly map your verified identity to a local account and role. Email address matching does not grant access.';return}throw e}}
async function signOutIdentity(){state.identityError=null;if(state.authConfig.mode==='clerk'){if(!state.clerk)throw Error('Identity provider is unavailable. Reload this page before trying again.');clearPrivateState();await state.clerk.signOut();history.replaceState(null,'','/#discover');await route()}else{await api('/api/logout',{});clearPrivateState();if(location.hash==='#discover')await route();else location.hash='discover'}}
function unmountIdentityWidget(){const widget=state.identityWidget;if(!widget)return;state.identityWidget=null;if(state.clerk)state.clerk[widget.signup?'unmountSignUp':'unmountSignIn'](widget.node)}
async function clerkLogin(signup=false){if(state.identityWidget?.signup===signup&&document.contains(state.identityWidget.node))return;const path=signup?'/auth/sign-up':'/auth/sign-in';if(!location.pathname.startsWith(path))history.replaceState(null,'',path);shell(head('Clerk identity',signup?'Create your identity.':'Sign in securely.','Identity verification is separate from property access, operator authorization and investor eligibility.')+`<div class="login-wrap"><section class="panel"><div class="notice">Clerk identity mode is configured. Live sign-in has ${state.authConfig.live_verified?'been verified by the operator':'not yet been independently verified for this deployment'}.</div>${state.identityError?`<div class="notice warning" role="alert">${esc(state.identityError)}</div>`:''}${state.clerk?.session?`<p class="small muted">You have an active provider session. Workspace membership requires explicit administrator provisioning.</p><div class="row"><button class="btn" id="identity-recheck">Check workspace access</button><button class="btn secondary" id="identity-signout">Sign out of Clerk</button></div>`:state.clerk?'<div id="clerk-auth" aria-label="Clerk authentication"></div>':'<div class="notice error">Clerk is unavailable. Refresh after the operator has corrected the identity configuration. No local password fallback is enabled.</div>'}</section></div>`);$('#identity-recheck')?.addEventListener('click',e=>perform(e.target,async()=>{await refreshIdentitySession();if(state.user){history.replaceState(null,'','/#workspace');await route()}else await clerkLogin(signup)}));$('#identity-signout')?.addEventListener('click',e=>perform(e.target,signOutIdentity));const node=$('#clerk-auth');if(node){state.identityWidget={node,signup};const options={routing:'path',path,forceRedirectUrl:`${location.origin}/#discover`,signInUrl:`${location.origin}/auth/sign-in`,signUpUrl:`${location.origin}/auth/sign-up`};state.clerk[signup?'mountSignUp':'mountSignIn'](node,options)}}
const $=(s)=>document.querySelector(s);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v)=>v==null?'Not disclosed':new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(Number(v));
const label=(s)=>String(s??'Unknown').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());
const arr=(x)=>Array.isArray(x)?x:[];
// Preserve source fields while adapting the server's explicit state vocabulary for presentation.
function present(value){if(Array.isArray(value))return value.map(present);if(!value||typeof value!=='object')return value;const r=Object.fromEntries(Object.entries(value).map(([k,v])=>[k,present(v)]));if(r.status===undefined&&r.state!==undefined)r.status=r.state;if(r.verification_state===undefined&&r.verification!==undefined)r.verification_state=r.verification;if(r.amount===undefined&&r.principal_cents!==undefined)r.amount=r.principal_cents/100;return r}
const json=(x)=>esc(JSON.stringify(x,null,2));
const inspectRecords=new Map();let inspectSequence=0;
function decodeRecord(value,depth=0){if(depth>20)return value;if(typeof value==='string'&&value.length<500000&&/^[\s]*[\[{]/.test(value)){try{return decodeRecord(JSON.parse(value),depth+1)}catch{return value}}if(Array.isArray(value))return value.map(v=>decodeRecord(v,depth+1));if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,decodeRecord(v,depth+1)]));return value}
function recordFields(value,depth=0){if(value===null)return '<span class="muted">Not recorded</span>';if(typeof value!=='object'){if(typeof value==='string'&&/^https?:\/\/[^\s]+$/i.test(value))return `<a class="record-value link" href="${esc(value)}" target="_blank" rel="noopener noreferrer">${esc(value)}</a>`;return `<span class="record-value">${esc(value)}</span>`}const entries=Object.entries(value);if(!entries.length)return '<span class="muted">No entries</span>';return `<dl class="record-fields ${depth?'nested':''}">${entries.map(([key,v])=>`<div class="record-field ${v&&typeof v==='object'?'record-field-wide':''}"><dt>${esc(Array.isArray(value)?`Item ${Number(key)+1}`:label(key))}</dt><dd>${depth>=10?`<pre>${json(v)}</pre>`:recordFields(v,depth+1)}</dd></div>`).join('')}</dl>`}
function inspectButton(record,title='Inspect'){const token=`record-${++inspectSequence}`;inspectRecords.set(token,record);return `<button type="button" class="btn secondary inspect-toggle" id="${token}-toggle" data-inspect="${token}" aria-expanded="false" aria-controls="${token}-detail">${esc(title)} <span aria-hidden="true">＋</span></button>`}
function recordPanel(token,record){return `<section class="record-panel" aria-labelledby="${token}-heading"><div class="record-toolbar"><div><div class="eyebrow">Record detail</div><h3 id="${token}-heading">${esc(label(record.event||record.action||record.agent_id||record.field||record.kind||'Evidence record'))}</h3></div><div class="row"><button type="button" class="btn secondary record-download" data-download="${token}">Download JSON ↓</button><button type="button" class="btn ghost record-close" data-close="${token}" aria-label="Close record detail">Close ×</button></div></div><p class="small muted">JSON-encoded fields are decoded below for reading. The download retains their stored representation.</p>${recordFields(decodeRecord(record))}</section>`}
const riskItems=x=>Array.isArray(x)?x:x&&typeof x==='object'?Object.entries(x).map(([k,v])=>({description:`${label(k)}: ${typeof v==='object'?JSON.stringify(v):v}`})):[];
function scenarios(s){return `<div class="metric-grid">${Object.entries(s.results||{}).map(([name,r])=>`<div class="stat"><div class="eyebrow">${esc(label(name))}</div><div class="stat-label" style="margin-top:12px">Annual net operating income</div><div class="stat-value">${money(r.noi)}</div><div class="small">DSCR <strong>${r.dscr==null?'Unknown':Number(r.dscr).toFixed(2)+'×'}</strong></div><hr class="divider"><div class="small">Debt service ${money(r.annual_debt_service)}</div><div class="small">Cash flow ${money(r.cash_flow_after_reserves)}</div><div class="small">Cash yield ${r.cash_yield==null?'Unknown':(r.cash_yield*100).toFixed(2)+'%'}</div><div class="small">Model estimate ${money(r.model_estimate)}</div></div>`).join('')}</div><p class="small muted">Calculated scenarios · not an appraisal, market quote or guarantee. Formula ${esc(s.formula_version||'recorded in snapshot')}.</p><details><summary class="small">Assumptions, evidence references & full snapshot</summary><pre>${json(s)}</pre></details>`}
function offeringCard(o){return `<div class="metric-grid"><div class="stat"><div class="stat-label">Simulation target</div><div class="stat-value">${money(o.target_cents/100)}</div></div><div class="stat"><div class="stat-label">Minimum subscription</div><div class="stat-value">${money(o.min_cents/100)}</div></div><div class="stat"><div class="stat-label">Simulation fee</div><div class="stat-value">${(o.fee_bps/100).toFixed(2)}%</div></div></div><p>${status(o.state)}</p><details><summary class="small">Offering record</summary><pre>${json(o)}</pre></details>`}
function ledger(rows,distribution=false){return table(arr(rows),[['Recorded',r=>esc(r.created_at)],['Type',r=>esc(label(r.kind||r.type||(distribution?'distribution':'transaction')))],['Amount · CAD',r=>money(r.amount_cents/100)],['State',r=>status(r.state||'allocated simulation')],['Record',r=>inspectButton(r)]])}
function subscriptionForm(o){return `<form id="subscribe" class="stack"><label>Simulation subscription · CAD<input name="amount" type="number" min="${o.min_cents/100}" step="0.01" required></label><div id="fee-preview" class="notice">Enter an amount to preview the simulation fee and total.</div><label class="row" style="flex-direction:row"><input style="width:auto" name="acknowledge" type="checkbox" required> I understand this is a simulation with a ${(o.fee_bps/100).toFixed(2)}% fee. No real investment, legal ownership or money transfer occurs.</label><button class="btn">Record simulated subscription</button></form>`}
function reconcileFields(){return `<label>Selected confirmed claim ID<input name="claim_id" required placeholder="Copy the selected claim ID from the data room"></label><p class="small muted">Select an already-confirmed financial or units claim. Original evidence remains preserved. The originator must calculate a new model snapshot after reconciliation.</p>`}
function claimSource(c){return `${esc(c.source_reference||c.source||c.artifact_id||'Structured intake')}<div class="provenance-action">${inspectButton(c,'Provenance')}</div>`}
const status=(s)=>`<span class="badge ${/pending|draft|review|quarantine|unverified/i.test(s)?'warn':/blocked|reject|fail/i.test(s)?'red':'neutral'}">${esc(label(s))}</span>`;
async function api(path,body){const requestedHash=location.hash,requestedIdentity=state.identityRevision||0;const identity=await identityHeaders(path);const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...identity,...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...(state.operatorKey&&path.startsWith('/api/network')?{'X-Operator-Key':state.operatorKey}:{})},credentials:'same-origin',...(body===undefined?{}:{body:JSON.stringify(body)})});let d;try{d=await r.json()}catch{throw Error(`Request failed (${r.status})`)}if(!r.ok){const e=Error(typeof d.error==='string'?d.error:d.error?.message||d.message||`Request failed (${r.status})`);e.status=r.status;e.detail=d;throw e}if(body===undefined&&((path!=='/api/session'&&requestedHash!==location.hash)||requestedIdentity!==(state.identityRevision||0))){const e=Error('Navigation changed');e.stale=true;throw e}return present(d)}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').style.display='none',6000)}
function building(i=0){const bg=['#d8e2da','#d9dfdd','#e5e0d3'][i%3], facade=['#b5ab92','#abb4a8','#bba994'][i%3];return `<svg viewBox="0 0 500 245" role="img" aria-label="Synthetic architectural illustration"><rect width="500" height="245" fill="${bg}"/><path d="M0 205L500 173V245H0Z" fill="#becdbd"/><path d="M40 221L497 210" stroke="#f7f8ef" stroke-width="6"/><path d="M114 62L310 39L379 70V207L114 220Z" fill="${facade}"/><path d="M310 39L379 70V207L310 184Z" fill="#829184"/><path d="M104 62L310 32L387 64L377 75L310 48L112 75Z" fill="#566e64"/>${Array.from({length:5},(_,r)=>Array.from({length:7},(_,c)=>`<path d="M${130+c*25} ${82+r*24-c*2.8}v14l13 -1.5v-14Z" fill="${(r+c)%4===0?'#d9d8b0':'#617c75'}"/>`).join('')).join('')}<path d="M222 175L251 171V211L222 214Z" fill="#506b62"/><path d="M91 229V166M416 214V150" stroke="#738775" stroke-width="5"/><ellipse cx="91" cy="160" rx="27" ry="43" fill="#8ca78b"/><ellipse cx="416" cy="150" rx="25" ry="42" fill="#8ca78b"/><path d="M0 244L500 221" stroke="#8c9e8b" stroke-width="2"/></svg>`}
function map(){return `<div class="map"><svg viewBox="0 0 650 170" role="img" aria-label="Conceptual Greater Toronto Area map, not exact coordinates"><rect width="650" height="170" fill="#e8ecdf"/><path d="M230 170L390 77L469 75L650 119V170Z" fill="#c2d8d5"/><g stroke="#fff" stroke-width="5"><path d="M0 55L580 13M20 115L550 57M90 0L140 170M223 0L259 151M340 0L358 100M450 0L463 75"/></g><path d="M0 81L342 40L613 66" fill="none" stroke="#d5c89e" stroke-width="6"/><g font-size="10" fill="#647b6c"><text x="40" y="139">MISSISSAUGA</text><text x="200" y="48">VAUGHAN</text><text x="358" y="43">MARKHAM</text><text x="338" y="126">LAKE ONTARIO</text></g><g fill="#087e76" stroke="white" stroke-width="3"><circle cx="294" cy="105" r="7"/><circle cx="211" cy="89" r="7"/><circle cx="375" cy="66" r="7"/></g><text x="305" y="99" fill="#244b43" font-size="11">TORONTO</text></svg><span class="map-label">Conceptual geography · markers are illustrative</span></div>`}
const navs=[['discover','▦','Discover'],['mandates','↗','Mandates'],['workspace','▤','My workspace'],['portfolio','◈','My portfolio'],['admin','◇','Command center'],['audit','≋','Evidence & audit'],['factory','⌘','Software factory'],['network','⌁','Private network']];
function shell(content){unmountIdentityWidget();const active=location.hash.slice(1).split('/')[0]||'discover';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#discover"><span class="brand-mark">r</span>realassetnet<span style="color:#a4cbb5">.</span></a><div class="subbrand">REAL ASSETS. REAL EVIDENCE.</div><div class="nav-label">Private deal network</div><nav class="nav" aria-label="Main navigation">${navs.filter(([id])=>id!=='network'||state.user?.role==='admin').map(([id,icon,text])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${text}</a>`).join('')}</nav><div class="side-bottom"><span class="environment">V0 · SIMULATION</span><div>Evidence-led introductions.<br>Closing stays with professionals.</div><hr class="divider"><div>Toronto / Greater Toronto Area<br>Canadian dollars · CAD</div></div></aside><main class="main"><header class="topbar"><div class="crumb">RealAssetNet <span style="padding:0 10px;color:#bcc4bd">/</span> ${esc(navs.find(x=>x[0]===active)?.[2]||'Property workspace')}</div><div class="top-actions"><span class="region">◉ Toronto / GTA</span>${state.user?`<span class="avatar">${esc(state.user.name?.slice(0,2).toUpperCase())}</span><span class="small">${esc(state.user.name)} <span class="muted">· ${esc(label(state.user.role))}</span></span><button class="btn ghost" id="logout">Sign out</button>`:`<a class="btn secondary" href="#login">Sign in</a>`}</div></header><div class="content">${content}<footer class="footer"><span>RealAssetNet · Evidence before execution</span><span>Financial execution is simulated. No live investments, payments or eligibility determinations.</span></footer></div></main></div>`;$('#logout')?.addEventListener('click',async()=>{try{await signOutIdentity()}catch(e){toast(e.message)}})}
function head(kicker,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><div class="muted small">${description}</div></div>${action}</div>`}
function stats(items){return `<div class="stats">${items.map(([title,value,note])=>`<div class="stat"><div class="stat-label">${esc(title)}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`).join('')}</div>`}
function propertyCard(p,i){return `<article class="card"><div class="property-image">${building(i)}${status(p.status||'public passport')}<span class="art-caption">Synthetic illustration</span></div><div class="card-body">${p.data_classification==='REAL_PRIVATE'?'<div class="badge warn">REAL PROPERTY · PRIVATE</div>':''}<div class="label">${esc(label(p.property_type||p.asset_class||'Real estate'))}</div><h3 class="card-address">${esc(p.address||p.title||p.name||'Property')}</h3><div class="card-location">${esc(p.city||'Toronto')} · Ontario</div><div class="property-meta"><span>${p.units?`${esc(p.units)} units`:'Units not disclosed'}</span><span>Property passport</span></div><div class="card-footer"><div><div class="label">Asking price</div><div class="price">${money(p.asking_price)}</div></div><a class="btn secondary" href="#property/${encodeURIComponent(p.id)}">View asset ↗</a></div></div></article>`}
async function discover(){
  const d=await api('/api/properties');
  state.properties=arr(d.properties);
  const opportunityHref=state.user?'#create':'#signup';
  const capitalHref=state.user?'#portfolio':'#signup';
  const verificationHref=state.user?'#workspace':'#signup';
  shell(`<section class="discover-hero">
    <div class="discover-hero-copy">
      <div class="eyebrow">RealAssetNet Discover</div>
      <h1>Bring the right deal.<br>Meet the right counterparty.<br>Move with evidence.</h1>
      <p class="discover-lead">A private deal-introduction and evidence workspace for developers, licensed mortgage professionals, appraisers, lawyers and capital partners.</p>
      <p class="discover-support">Share a confidential mandate, accept a relevant introduction, then work through a controlled diligence process. RealAssetNet does not take custody of money or replace licensed closing professionals.</p>
    </div>
    <figure class="discover-hero-image"><img src="/hero-toronto.png" alt="Toronto skyline and contemporary residential architecture"><figcaption>Toronto / GTA first · Concept image</figcaption></figure>
  </section>
  <section class="decision-section" aria-labelledby="participate-title">
    <div class="decision-heading"><div><div class="eyebrow">Choose your next step</div><h2 id="participate-title">Tell us how you participate.</h2></div><p>One clear starting point. Your private details stay private until an authorized workflow requires them.</p></div>
    <div class="decision-grid">
      <article class="decision-card decision-primary"><div class="decision-number">01</div><h3>I have a deal</h3><p>Bring a property, financing need or disposition mandate and prepare it for controlled review.</p><span class="decision-audience">Owners · developers · brokers</span><a class="btn" href="${opportunityHref}">Submit a mandate <span aria-hidden="true">→</span></a></article>
      <article class="decision-card"><div class="decision-number">02</div><h3>I have capital or financing capacity</h3><p>Set your mandate and receive relevant opportunities after a mutual, permissioned introduction.</p><span class="decision-audience">Lenders · investors · mortgage professionals</span><a class="btn secondary" href="${capitalHref}">Request partner access <span aria-hidden="true">→</span></a></article>
      <article class="decision-card"><div class="decision-number">03</div><h3>I verify transactions</h3><p>Join the controlled evidence workflow as an appraiser, lawyer or specialist advisor.</p><span class="decision-audience">Appraisers · lawyers · advisors</span><a class="btn secondary" href="${verificationHref}">Request workspace access <span aria-hidden="true">→</span></a></article>
    </div>
  </section>
  <section class="privacy-promise"><div><div class="eyebrow">Confidential by design</div><h2>Details are redacted until both sides agree.</h2></div><p>We help relevant parties find each other. Identity, address-level detail and supporting documents remain inside a permissioned evidence workflow.</p></section>
  <section class="process-section" aria-labelledby="process-title"><div class="section-row"><div><div class="eyebrow">A simple controlled process</div><h2 id="process-title">From mandate to a closing handoff.</h2></div><span class="small muted">Evidence before execution</span></div><ol class="process-list"><li><b>1</b><div><h3>Submit a mandate</h3><p>Describe what you have or what you need.</p></div></li><li><b>2</b><div><h3>Accept an introduction</h3><p>Relevant counterparties choose whether to connect.</p></div></li><li><b>3</b><div><h3>Enter an evidence room</h3><p>Share documents, questions and review history with access controls.</p></div></li><li><b>4</b><div><h3>Close with professionals</h3><p>Licensed legal, lending and closing parties retain their proper roles.</p></div></li></ol></section>
  <section class="passport-section"><div class="section-row"><div><div class="eyebrow">Public discovery</div><h2>Explore reviewed property passports.</h2></div><span class="small muted" id="result-count">${state.properties.length} available</span></div><div class="filters"><input id="search" type="search" placeholder="Search city or property type" aria-label="Search property passports"><select id="type-filter" aria-label="Property type"><option value="">All property types</option>${[...new Set(state.properties.map(p=>p.property_type).filter(Boolean))].map(v=>`<option>${esc(v)}</option>`).join('')}</select><select id="city-filter" aria-label="City"><option value="">All cities</option>${[...new Set(state.properties.map(p=>p.city).filter(Boolean))].map(v=>`<option>${esc(v)}</option>`).join('')}</select></div><div class="grid" id="property-grid">${state.properties.map(propertyCard).join('')||'<div class="empty">No public passports yet. Submit a mandate to begin a private, evidence-led workflow.</div>'}</div></section>`);
  const filter=()=>{const q=$('#search').value.toLowerCase(),t=$('#type-filter').value,c=$('#city-filter').value;const list=state.properties.filter(p=>`${p.address} ${p.city} ${p.property_type}`.toLowerCase().includes(q)&&(!t||p.property_type===t)&&(!c||p.city===c));$('#property-grid').innerHTML=list.map(propertyCard).join('')||'<div class="empty">No matching property passports.</div>';$('#result-count').textContent=`${list.length} available`};
  ['search','type-filter','city-filter'].forEach(id=>$('#'+id).addEventListener('input',filter));
}
async function login(signup=false){if(state.authConfig.mode==='clerk')return clerkLogin(signup);if(state.authConfig.mode!=='demo'){shell(head('Identity unavailable','Sign-in configuration is unavailable.',esc(state.identityError||'Ask the operator to check the configured identity provider.')));return}shell(head('Your workspace','Welcome to RealAssetNet.','A controlled environment for property evidence and transaction workflows.')+`<div class="login-wrap"><div class="notice">Local demo identity · Clerk is not configured or active.</div><section class="panel"><h2>${signup?'Create your workspace':'Sign in'}</h2><form id="auth" class="stack">${signup?'<label>Full name<input name="name" required maxlength="100" autocomplete="name"></label><label>Organization<input name="organization" required maxlength="120" autocomplete="organization"></label><label>Role<select name="role"><option value="broker">Broker</option><option value="owner">Property owner</option><option value="investor">Investor</option></select></label>':''}<label>Business email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required minlength="12" autocomplete="${signup?'new-password':'current-password'}"></label><button class="btn" type="submit">${signup?'Create account':'Sign in'} →</button><div id="form-error" role="alert"></div></form><p class="small muted">${signup?'Already have an account? <a class="link" href="#login">Sign in</a>':'New here? <a class="link" href="#signup">Create a workspace</a>'}</p></section>${!signup?`<section class="panel"><div class="eyebrow">Guided demonstration</div><h3 style="margin-top:12px">Try each side of the workflow</h3><p class="small muted">These seeded accounts operate exclusively in the local simulation. Each role has different permissions.</p><div class="login-demo">${['broker','reviewer','investor'].map(r=>`<button class="btn secondary demo" data-role="${r}">${label(r)} demo</button>`).join('')}</div></section>`:''}</div>`);$('.demo')&&document.querySelectorAll('.demo').forEach(b=>b.onclick=()=>{$('[name=email]').value=`${b.dataset.role}@demo.invalid`;$('[name=password]').value='DemoOnly!2026'});$('#auth').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api(signup?'/api/signup':'/api/login',Object.fromEntries(new FormData(e.target)));const s=await api('/api/session');Object.assign(state,s);location.hash=state.user?.role==='admin'||state.user?.role==='reviewer'?'admin':state.user?.role==='investor'?'discover':'workspace'}catch(err){$('#form-error').textContent=err.message}finally{b.disabled=false}}}
function requireUser(){if(state.user)return true;shell(head('Permissioned workspace','Sign in to continue.',esc(state.identityError||'Your organization’s private property evidence is available only to authorized accounts.'),`<a class="btn" href="#login">Sign in →</a>`));return false}
async function mandates(){if(!requireUser())return;const d=await api('/api/mandates'),mine=arr(d.mine),available=arr(d.available),matches=arr(d.matches),invites=arr(d.invitations);const own=mine.map(m=>`<article class="mandate-card"><div class="row space"><span class="badge ${m.data_classification==='REAL_PRIVATE'?'warn':'neutral'}">${esc(label(m.data_classification))}</span>${status(m.state)}</div><div class="label">${esc(label(m.kind))} · ${esc(label(m.intent))}</div><h3>${esc(label(m.asset_subtype))} · ${esc(m.market)}</h3><p class="small muted">${esc(m.jurisdiction)} · ${esc(m.timeline)}<br>${m.consent_to_matching?'Explicit matching consent recorded.':'Draft — not in matching pool.'}</p>${m.state==='DRAFT'?`<button class="btn" data-submit-mandate="${esc(m.id)}">Submit to redacted matching</button>`:'<div class="small muted">Terms and property linkage remain private.</div>'}</article>`).join('')||'<div class="empty">Create a structured opportunity or capital request. It stays private until you explicitly submit it.</div>';const pool=available.map(m=>`<article class="mandate-card"><span class="badge neutral">REDACTED MATCHING PROFILE</span><div class="label">${esc(label(m.kind))} · ${esc(label(m.intent))}</div><h3>${esc(label(m.asset_subtype))} · ${esc(m.market)}</h3><p class="small muted">${esc(m.asset_class)} · ${esc(m.jurisdiction)} · ${esc(m.timeline)}</p><p class="small">Identity, address, pricing, terms and evidence are withheld. A reviewer may propose a match only where both sides opted in.</p></article>`).join('')||'<div class="empty">No consented counterparty profiles are available yet.</div>';shell(head('Mandates','Bring a deal. State a need.','Structured introductions for professional counterparties — with controlled disclosure, not automated outreach.',`<a class="btn" href="#mandate-new">＋ Create mandate</a>`)+`<div class="notice warning">${esc(d.notice)} This is an introduction workflow, not a listing, lending, securities, escrow, closing, appraisal, or legal service.</div><section class="mandate-section"><div class="section-row"><h2>Your mandates</h2><span class="pill">Private by default</span></div><div class="mandate-grid">${own}</div></section><section class="mandate-section"><div class="section-row"><h2>Compatible, redacted profiles</h2><span class="pill">No identity or evidence disclosed</span></div><div class="mandate-grid">${pool}</div></section><section class="panel"><h2>Match decisions</h2><p class="small muted">Both organizations must accept a reviewer-proposed match before a reviewer may issue a room invitation.</p>${matches.map(m=>`<div class="match-row"><div><strong>${esc(label(m.asset_class))} · ${esc(m.jurisdiction)}</strong><div class="small muted">${esc(m.rationale)} · ${esc(m.my_side)} party</div></div><div class="row">${status(m.state)}${m.can_respond?`<button class="btn secondary" data-match-response="${esc(m.id)}" data-accepted="false">Decline</button><button class="btn" data-match-response="${esc(m.id)}" data-accepted="true">Accept</button>`:''}</div></div>`).join('')||'<div class="small muted">No reviewer-proposed matches yet.</div>'}</section><section class="panel"><h2>Evidence-room invitations</h2>${invites.map(i=>`<div class="match-row"><div><strong>${esc(label(i.asset_class))} evidence room</strong><div class="small muted">Invitation ${esc(i.state)} · access is not granted until you accept.</div></div>${i.state==='PENDING'?`<button class="btn" data-invite-accept="${esc(i.id)}">Accept invitation</button>`:`<a class="btn secondary" href="#room/${encodeURIComponent(i.property_id)}">Open room</a>`}</div>`).join('')||'<div class="small muted">No evidence-room invitations.</div>'}</section>`);document.querySelectorAll('[data-submit-mandate]').forEach(b=>b.onclick=()=>perform(b,async()=>{await api(`/api/mandates/${encodeURIComponent(b.dataset.submitMandate)}/submit`,{consent_to_matching:true});toast('Mandate submitted to the redacted matching pool.');await mandates()}));document.querySelectorAll('[data-match-response]').forEach(b=>b.onclick=()=>perform(b,async()=>{await api(`/api/matches/${encodeURIComponent(b.dataset.matchResponse)}/respond`,{accepted:b.dataset.accepted==='true'});toast(b.dataset.accepted==='true'?'Acceptance recorded.':'Match declined.');await mandates()}));document.querySelectorAll('[data-invite-accept]').forEach(b=>b.onclick=()=>perform(b,async()=>{await api(`/api/invitations/${encodeURIComponent(b.dataset.inviteAccept)}/accept`,{});toast('Evidence-room access granted and audited.');await mandates()}))}
async function mandateNew(){if(!requireUser())return;const w=await api('/api/workspace');shell(head('New mandate','Make the request clear.','Only the matching profile is shown to opted-in counterparties. Identity, property linkage, requirements and value details stay private.')+`<div class="two-col"><form id="mandate-form" class="panel stack"><label>Mandate type<select name="kind"><option value="OPPORTUNITY">Structured opportunity</option><option value="CAPITAL_REQUEST">Capital request</option></select></label><div class="form-grid"><label>Asset class<select name="asset_class"><option value="REAL_ESTATE">Real estate</option><option value="ART_COLLECTIBLE">Art / collectible</option><option value="OTHER_PRIVATE_ASSET">Other private asset</option></select></label><label>Asset subtype<input name="asset_subtype" placeholder="e.g. condominium, multifamily" required></label></div><div class="form-grid"><label>Jurisdiction context<select name="jurisdiction"><option value="CA-ON">Canada · Ontario</option><option value="GB-ENG">United Kingdom · England</option><option value="US-FL">United States · Florida</option><option value="OTHER">Other</option></select></label><label>Market<input name="market" placeholder="e.g. Toronto GTA" required></label></div><label>Intent<select name="intent"><option value="ACQUISITION">Acquisition</option><option value="DISPOSITION">Disposition</option><option value="FINANCING">Financing</option><option value="REFINANCING">Refinancing</option><option value="DILIGENCE">Diligence</option><option value="ADVISORY">Advisory</option></select></label><div class="form-grid"><label>Value minimum (optional)<input name="value_min" type="number" min="0"></label><label>Value maximum (optional)<input name="value_max" type="number" min="0"></label></div><label>Currency<select name="currency"><option>CAD</option><option>USD</option><option>GBP</option></select></label><label>Timeline<input name="timeline" placeholder="e.g. 90 days" required></label><label>Requirements (private until permitted)<textarea name="requirements" required placeholder="Describe requirements without uploading sensitive documents."></textarea></label><label>Optional property workspace link<select name="property_id"><option value="">No property room yet</option>${arr(w.properties).map(p=>`<option value="${esc(p.id)}">${esc(p.address)} · ${esc(p.city)}</option>`).join('')}</select></label><label>Record classification<select name="data_classification"><option value="DEMO_SYNTHETIC">Demo / synthetic</option><option value="REAL_PRIVATE">Real private information</option></select></label><label class="row" style="flex-direction:row"><input style="width:auto" name="rights_attested" type="checkbox"> I have authority to provide private information for controlled review.</label><label class="row" style="flex-direction:row"><input style="width:auto" name="consent" type="checkbox" required> I explicitly consent to a redacted matching profile. No automated outreach or evidence disclosure is authorized.</label><button class="btn">Create and submit mandate</button></form><aside class="panel"><h2>What happens next</h2><ol class="checklist"><li>Your detailed mandate is private to your organization.</li><li>Only a redacted profile can appear after explicit consent.</li><li>An independent reviewer may propose a compatible match.</li><li>Both parties accept before a reviewer can issue a specific room invitation.</li></ol><div class="notice">Jurisdiction and asset class are routing context only. They do not establish eligibility, licensing, valuation, legal coverage, or a fund structure.</div></aside></div>`);$('#mandate-form').onsubmit=e=>{e.preventDefault();perform(e.submitter,async()=>{const v=Object.fromEntries(new FormData(e.target));v.rights_attested=e.target.rights_attested.checked;for(const k of ['value_min','value_max'])if(v[k]==='')delete v[k];else v[k]=Number(v[k]);const made=await api('/api/mandates',v);await api(`/api/mandates/${encodeURIComponent(made.mandate.id)}/submit`,{consent_to_matching:true});toast('Mandate is now available as a redacted profile.');location.hash='mandates'})}}
async function workspace(){if(!requireUser())return;const d=await api('/api/workspace');const ps=arr(d.properties);shell(head('Origination workspace','Build a stronger property record.','Create a passport, review source claims and submit an evidence-backed property for review.',`<a class="btn" href="#create">＋ Add a property</a>`)+`<div class="notice">Start with property facts → upload safe text evidence → confirm each extracted claim → calculate a versioned model → submit for independent review.</div><div class="grid">${ps.map((p,i)=>propertyCard(p,i).replace(`#property/`,`#room/`).replace('View asset ↗','Open workspace ↗')).join('')||'<div class="empty">Your workspace is empty. Add your first property to begin.</div>'}</div>`)}
async function create(){if(!requireUser())return;shell(head('Property intake','Give this asset a clear starting point.','Create a private property record. Publication requires evidence review.')+`<section class="panel" style="max-width:820px"><div class="stepper"><div class="step"><b>1</b> Property facts</div><div class="step"><b>2</b> Source evidence</div><div class="step"><b>3</b> Independent review</div></div><form id="create" class="form-grid">${classificationFields()}<label class="full">Property address<input name="address" required maxlength="200" placeholder="Street address"></label><label>City<select name="city">${['Toronto','Mississauga','Brampton','Vaughan','Markham','Richmond Hill','Oakville','Burlington','Pickering','Ajax','Whitby','Oshawa'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Property type<select name="property_type">${['MULTIFAMILY','RESIDENTIAL_PORTFOLIO','MIXED_USE','INDUSTRIAL_LOGISTICS','OFFICE','RETAIL','HOSPITALITY','DEVELOPMENT','LAND'].map(c=>`<option value="${c}">${label(c)}</option>`).join('')}</select></label><label>Units<input name="units" type="number" min="1" step="1" required></label><label>Asking price · CAD<input name="asking_price" type="number" min="1" step="1" required></label><label class="full">Property description<textarea name="description" maxlength="2000" placeholder="Describe the property without unsupported performance claims."></textarea></label><div class="full row"><button class="btn" type="submit">Create private record →</button><a class="btn ghost" href="#workspace">Cancel</a><span id="form-error" role="alert"></span></div></form></section>`);$('#create').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.units=Number(v.units);v.asking_price=Number(v.asking_price);v.rights_attested=e.target.rights_attested.checked;await perform(e.submitter,async()=>{const d=await api('/api/properties',v);location.hash=`room/${d.property.id}`})}}
async function publicProperty(id){const {property:p}=await api(`/api/properties/${encodeURIComponent(id)}`);shell(head('Public property passport',esc(p.address||p.name),`${esc(p.city||'Toronto')} · ${esc(label(p.property_type))}`,`<a class="btn" href="#room/${encodeURIComponent(id)}">Open controlled data room →</a>`)+`<div class="two-col"><section class="card"><div class="property-image" style="height:290px">${building(0)}<span class="art-caption">Synthetic illustration · not property photography</span></div><div class="card-body"><div class="row space"><div><div class="label">Asking price</div><h2>${money(p.asking_price)}</h2></div>${status(p.status||'Published')}</div><p class="small muted">Originator: ${esc(p.originator||'Not publicly disclosed')}</p><p>${esc(p.description||'Supporting property details are available through a controlled evidence workflow.')}</p><div class="property-meta"><span>${esc(p.units??'Unknown')} units</span><span>${esc(label(p.property_type))}</span><span>${esc(p.city)}</span></div></div></section><div><section class="panel"><h2>Evidence has an access boundary.</h2><p class="small muted">This passport presents public property facts. Source documents, operating figures, underwriting and transaction materials require an explicit access grant.</p><ul class="checklist"><li>Property facts separated from financial models</li><li>Source claims reviewed individually</li><li>Versioned underwriting assumptions</li><li>No investment or legal clearance implied</li></ul><a class="btn secondary" href="#room/${encodeURIComponent(id)}">Check my access ↗</a></section>${map()}</div></div>`)}
